import{_ as t,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学日报 | 2026年8月12日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-08-12.md","filePath":"science-log/src/science-daily/2026-08-12.md"}'),s={name:"science-log/src/science-daily/2026-08-12.md"};function u(i,o,a,q,c,g){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="🔬-科学日报-2026年8月12日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年8月12日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年8月12日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年8月12日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：本日无当日简讯，采用<strong>事后重建版简讯</strong>（science-log/src/reconstructed/2026-08-12.md，共 10 条：科学前沿 5 + AI 前沿 5） 分析日期：2026-08-12 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-06 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><p>原文核验：全部 10 条均经 CrossRef / EuropePMC（DOI 反查摘要、作者、期刊、出版日）与 arXiv 元数据逐条确认；下方所有数字与结论均取自真实摘要，未作任何补写。</p><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-会-尝血糖-的口服益生菌-把降糖药做成活体传感器" tabindex="-1">1. 会&quot;尝血糖&quot;的口服益生菌：把降糖药做成活体传感器 <a class="header-anchor" href="#_1-会-尝血糖-的口服益生菌-把降糖药做成活体传感器" aria-label="Permalink to &quot;1. 会&quot;尝血糖&quot;的口服益生菌：把降糖药做成活体传感器&quot;">​</a></h3><p><strong>原文</strong>：现有&quot;设计细胞&quot;疗法要么依赖外部信号遥控，要么把合成基因网络装进哺乳动物细胞再移植，安全性与可及性都受限。该研究把葡萄糖感应器做进口服益生菌：用葡萄糖响应转录调控因子 HexR 加一个合成启动子搭成基因回路，细菌口服后短暂定植肠道，血糖越过正常阈值才启动治疗性转基因表达，形成&quot;感知—响应&quot;闭环。</p><p><strong>深度扩展</strong>：这项工作由 Ningzi Guan、Deqiang Kong、Xianyun Gao 等完成，<strong>Haifeng Ye</strong> 为末位（通讯）作者，共 13 位作者，2026-08-12 在线发表于 <em>Nature</em>（CrossRef 记录未附机构信息，团队所属单位未能核实）。方法上的关键不是&quot;工程菌&quot;，而是<strong>把血糖本身当作诱导信号</strong>：HexR 是细菌中天然响应葡萄糖代谢物的转录调控因子，团队把它与人工合成启动子拼成一个&quot;阈值门&quot;——血糖正常时回路沉默，血糖越过阈值才开启下游治疗性转基因。给药方式因此从注射/移植降级为口服，细菌只在肠道<strong>短暂定植</strong>，不整合进宿主基因组，避免了过去设计细胞疗法的移植风险与免疫排斥。</p><p>证据层面覆盖了两个物种：多种糖尿病小鼠模型之外，还做了非人灵长类（猴）实验——这是合成生物学活体药最难跨的一步。长期口服后观察到血糖控制改善、血脂谱明显好转，并延缓了多种糖尿病并发症的发生。缺陷也需如实指出：摘要未报告具体的 HbA1c 降幅、起效时滞与个体差异分布，也未说明长期定植的逃逸/水平基因转移风险如何监测，这些是走向临床前必须补齐的安全数据。</p><p>为什么重要：现有降糖治疗（胰岛素、GLP-1 受体激动剂、SGLT2 抑制剂）都是&quot;开环&quot;的——剂量由医生或患者按测量值决定，天然滞后于血糖波动。活体传感菌把控制环闭合到分钟级，且不需要外部供电、光源或无线遥控，本质上是把&quot;给药装置&quot;藏进了代谢系统本身。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 中合成生物学与活体药线索同源；其&quot;阈值门控 + 负反馈&quot;结构与 <code>topics/ai-brain/index.md</code> 讨论的控制器设计（何时该由规则接管、何时交给模型）在控制论层面同构。</p><hr><h3 id="_2-不用光照的超分辨-靠化学反应的光子做-100-nm-成像" tabindex="-1">2. 不用光照的超分辨：靠化学反应的光子做 ~100 nm 成像 <a class="header-anchor" href="#_2-不用光照的超分辨-靠化学反应的光子做-100-nm-成像" aria-label="Permalink to &quot;2. 不用光照的超分辨：靠化学反应的光子做 ~100 nm 成像&quot;">​</a></h3><p><strong>原文</strong>：超分辨荧光显微镜一直建立在&quot;外源光激发&quot;之上，而电化学发光（ECL）、化学发光（CL）、生物发光（BL）这类反应激发体系虽无需光照、灵敏度高，却因光子预算太低而被认为分辨率有天花板。作者提出 RIED，把&quot;时空记录策略&quot;与&quot;适配反应驱动光子统计的重建算法&quot;（熵加权相关 + 反卷积）结合的化学型超分辨框架，在 ECL / CL / BL 三种模态下对细胞内细胞器实现约 100 nm 分辨率。</p><p><strong>深度扩展</strong>：论文由 Wenxin Zhu、Chi Zhang、Jiahui Gui 等完成（2026-08-12，<em>Nature</em>），核心是把超分辨的核心矛盾从&quot;光学系统&quot;迁到&quot;光子统计&quot;。传统超分辨（STED / SIM / SMLM）靠强激光榨取非线性或稀疏开关；反应激发体系没有激光，光子由化学反应逐个产生，单帧光子数极低，直接套用既有算法信噪比不足。</p><p>RIED 的两段设计值得注意。第一段是<strong>时空记录</strong>：不再把发光当作&quot;瞬时光强&quot;，而是把反应发光的时间序列与空间位置一起记录，使化学反应的随机性成为信息而非噪声。第二段是<strong>熵加权相关 + 反卷积重建</strong>：用熵加权相关提取反应驱动光子分布中真正携带结构信息的成分（抑制低信息量的均匀背景），再做反卷积恢复被点扩散函数模糊的结构。这个组合让算法与&quot;反应驱动光子的统计特性&quot;匹配，而不是与&quot;激光激发的统计特性&quot;匹配——这是方法论上真正的迁移，而非参数调优。</p><p>结果：ECL、CL、BL 三种模态下对细胞内细胞器均达到约 100 nm 分辨率，并用于高灵敏成像。客观限制：100 nm 属&quot;低于衍射极限但尚不及 STORM/PALM 的 20 nm 级&quot;，其价值在于<strong>无外源光</strong>带来的活细胞兼容性与极低背景（化学发光无自发荧光），而非绝对分辨率纪录。若能在活细胞长时程观测中稳定工作，对光敏感样品（类器官、光敏蛋白标记、深组织）意义很大。</p><p><strong>跨主题关联</strong>：属 <code>topics/materials/index.md</code> 的发光材料/探针线索与 <code>topics/physics/index.md</code> 的成像物理交叉；&quot;把噪声统计当作信息载体&quot;这一思路与 <code>topics/ai-brain/index.md</code> 中&quot;检索噪声 vs 信号&quot;的讨论结构相同。</p><hr><h3 id="_3-在实体瘤里做全基因组-crispr-筛选-找到-t-细胞-衰竭总闸" tabindex="-1">3. 在实体瘤里做全基因组 CRISPR 筛选：找到 T 细胞&quot;衰竭总闸&quot; <a class="header-anchor" href="#_3-在实体瘤里做全基因组-crispr-筛选-找到-t-细胞-衰竭总闸" aria-label="Permalink to &quot;3. 在实体瘤里做全基因组 CRISPR 筛选：找到 T 细胞&quot;衰竭总闸&quot;&quot;">​</a></h3><p><strong>原文</strong>：人 T 细胞的大规模 CRISPR 筛选多在体外做，但实体瘤微环境里的调控因子体外表不出来；体内筛选又长期卡在&quot;瘤内 T 细胞回收率太低&quot;。作者建立了能高效从实体瘤回收人 T 细胞的体内模型，用少量小鼠即可完成全基因组敲除筛选。</p><p><strong>深度扩展</strong>：Qi Liu、Peixin Amy Chen、Esha Urs 等，2026-08-12，<em>Nature</em>。这项工作的技术突破点常被忽略：不是&quot;做了筛选&quot;，而是<strong>解决了体内筛选的工程死结</strong>——人 T 细胞注入荷瘤小鼠后，能从实体瘤中被高效回收，才使得全基因组尺度（而非几十个候选基因）在少量小鼠上可行。回收率一旦够，统计功效才成立。</p><p>筛选设计是双路的，这一点很讲究：一条筛&quot;瘤内丰度&quot;（哪些基因敲掉后 T 细胞更能进入/驻留肿瘤），一条筛&quot;效应功能&quot;（哪些基因敲掉后 T 细胞在抑制环境下仍能杀伤）。瘤内 T 细胞本身已呈现功能障碍特征，构成理想的筛选背景。</p><p>命中结果清晰且互补。丰度筛选指向 <strong>P2RY8–Gα13</strong> GPCR 信号轴为瘤内浸润的负调控者；效应功能筛选锁定 <strong>GNAS</strong>（编码 Gαs）为关键衰竭驱动因子，而 Gαs 是多个感知不同抑制性配体（前列腺素 E2、腺苷等经不同 GPCR）的<strong>汇聚节点</strong>——这意味着敲掉一个 GNAS，等于同时切断多条抑制通路，T 细胞对多种抑制信号脱敏。在 CAR 与 TCR 两类体系中、多种实体瘤模型上，GNAS 敲除均显著提升疗效；P2RY8 与 GNAS 联合敲除进一步提升肿瘤控制，说明两个靶点是正交的。</p><p>临床含义：CAR-T 在血液瘤成功、在实体瘤屡战屡败，长期归因于&quot;微环境太抑制&quot;。这项工作给出了可编辑的具体节点，并证明&quot;汇聚节点&quot;比&quot;单受体&quot;更值得打。待验证的是人体安全性——Gαs 参与大量正常 GPCR 信号，永久敲除的代价需要条件性/可逆编辑方案来兜。</p><p><strong>跨主题关联</strong>：接 <code>topics/biomedicine/index.md</code> 的 CAR-T 与肿瘤免疫线索；&quot;多输入汇聚到单一节点&quot;的拓扑与 <code>topics/ai-system-architecture/index.md</code> 中多源信号汇聚、单点故障的分析同构。</p><hr><h3 id="_4-双靶-sirna-同时-刹车-体细胞扩增与亨廷顿蛋白-效果协同" tabindex="-1">4. 双靶 siRNA：同时&quot;刹车&quot;体细胞扩增与亨廷顿蛋白，效果协同 <a class="header-anchor" href="#_4-双靶-sirna-同时-刹车-体细胞扩增与亨廷顿蛋白-效果协同" aria-label="Permalink to &quot;4. 双靶 siRNA：同时&quot;刹车&quot;体细胞扩增与亨廷顿蛋白，效果协同&quot;">​</a></h3><p><strong>原文</strong>：亨廷顿病（HD）的两个核心驱动是体细胞 CAG 重复扩增与毒性 HTT 片段，但此前从未被直接比较或联用。作者用二价 siRNA 在 Q111 模型小鼠（&gt;110 个 CAG，12 月龄已出现明显扩增、包涵体与转录失调）中分别沉默 MSH3、HTT 或两者：长期沉默 MSH3 阻断体细胞扩增、减少包涵体并让基因表达谱回归正常；单降 HTT 效果有限；而 MSH3/HTT 联合呈现协同获益。</p><p><strong>深度扩展</strong>：2026-08-12，<em>Science Translational Medicine</em>（DOI 10.1126/scitranslmed.aea3104）。这项研究的价值在<strong>实验设计而非单点发现</strong>：它第一次把 HD 疗法的两条路线放进同一个模型、同一时间尺度里正面对撞，并测试组合。</p><p>两条路线是什么？其一是&quot;降 HTT&quot;——用 RNAi/ASO 把突变亨廷顿蛋白的总量压下去，这是过去十年进入临床试验的主流思路；其二是&quot;阻断体细胞扩增&quot;——HD 的 CAG 重复在<strong>体细胞（尤其纹状体神经元）中会继续变长</strong>，随年龄增长而加重的扩增是疾病进展的分子引擎，而错配修复系统（MSH3、MSH2、MLH1 等）正是这台引擎的传动件。人群遗传学早就提示 MSH3 的变异能修饰发病年龄，但一直没人把它做成疗法并与降 HTT 直接比拼。</p><p>团队用<strong>二价 siRNA（divalent siRNA）<strong>实现长效沉默，在 Q111 knock-in 小鼠（&gt;110 个 CAG，12 月龄已有稳健扩增、突变 HTT 包涵体与转录失调）中做长期干预。结果分层很清楚：单独长期沉默 MSH3，体细胞扩增被阻断、包涵体减少、基因表达谱趋于正常——但注意，它并没有降低突变 HTT 的</strong>总量</strong>；单独降 HTT 效果有限——这与临床试验的失望结果相互印证；而 MSH3 + HTT 联合，效应是<strong>协同</strong>（synergize）而非简单相加。</p><p>机制解释由此闭合：只关扩增引擎，已有毒性片段仍在；只降总量，扩增引擎持续造新的更长片段。两者必须同时处理。全文 12 个月的长时程数据尤其关键——HD 是慢病，短期读数常常误导。</p><p>局限与待答：小鼠 Q111 模型不能完全代表人脑中选择性易损的纹状体环路；二价 siRNA 的中枢递送（鞘内 vs 全身）与长期安全性仍需评估；摘要未量化&quot;协同&quot;的具体效应量，协同的数学判据（Bliss / Loewe）是否成立需看正文。</p><p><strong>跨主题关联</strong>：属 <code>topics/biomedicine/index.md</code> 的神经退行性疾病线索，与 <code>topics/neuroscience/index.md</code> 的蛋白稳态/选择性易损讨论直接相接；&quot;两个必须同时关闭的驱动源&quot;这一结构，与 <code>topics/ai-brain/index.md</code> 中&quot;仅调输出不修上游约束则复发&quot;的观察同构。</p><hr><h3 id="_5-婴儿为何看几眼就会归类-日常视觉经验的-块状-统计结构" tabindex="-1">5. 婴儿为何看几眼就会归类：日常视觉经验的&quot;块状&quot;统计结构 <a class="header-anchor" href="#_5-婴儿为何看几眼就会归类-日常视觉经验的-块状-统计结构" aria-label="Permalink to &quot;5. 婴儿为何看几眼就会归类：日常视觉经验的&quot;块状&quot;统计结构&quot;">​</a></h3><p><strong>原文</strong>：一岁婴儿能从极少数样例迅速形成并泛化类别，这与机器学习&quot;小样本难泛化&quot;的困境形成对照。作者用 14 名婴儿、87 次进餐时段的头戴相机影像，量化 8 个物体类别的日常视觉统计：个体经验中各类实例的出现频次高度偏斜，用图论指标衡量则呈现&quot;块状&quot;（lumpy）结构，即高相似度与高变异并存，并组织成多个彼此连通的相似图像簇。</p><p><strong>深度扩展</strong>：2026-08-12，<em>PNAS</em>（DOI 10.1073/pnas.2536143123）。这项研究的方法学很有特点：它不去实验室里给婴儿看受控刺激，而是<strong>直接用头戴相机记录婴儿真实一天里看到了什么</strong>——14 名一岁婴儿、87 次进餐时段的头戴影像，覆盖 8 个物体类别。这是一份罕见的&quot;婴儿视觉训练集&quot;实测统计。</p><p>三项实测结果值得逐条拆。第一，<strong>频次高度偏斜</strong>：每个婴儿的经验里，少数几个物体反复出现（自己那套餐具、那把高脚椅），其余实例只是偶尔一瞥——这跟 ImageNet 式均衡采样完全不同。第二，<strong>类内变异大且不均</strong>：同一类别在不同实例间差异大，但个别实例内部又反复出现近乎相同的视角。第三，用图论指标衡量，个体经验呈现&quot;块状&quot;结构：多个高相似图像簇（同一物体的多帧）之间由少量&quot;桥接&quot;图像连通，形成稀疏的连通图而非均匀云团。</p><p>然后是最关键的计算实验：作者人工构造不同统计结构的训练集，发现由&quot;高相似簇 + 簇间桥接&quot;构成的训练集，能让模型在<strong>有限训练后泛化到新实例</strong>；而均衡但缺乏簇结构的训练集，泛化效率更低。也就是说，泛化能力的来源可能不是样本数量，而是经验的<strong>拓扑</strong>：反复看同一实例获得稳定的&quot;锚点表征&quot;，偶尔的变异提供&quot;可变维度&quot;，两者结合把类别定义在正确的轴上。</p><p>这意味着婴儿的&quot;少样本奇迹&quot;可能不是某种神奇的归纳偏置，而是<strong>数据分布本身就在帮他们</strong>——日常世界天然是块状、偏斜、聚集的。对 AI 的启示直接而尖锐：小样本学习的瓶颈也许不在模型容量或正则化，而在于训练数据的采集策略（是否能形成&quot;锚点 + 变异&quot;的簇结构）。</p><p>局限：样本量小（14 名婴儿、单一文化环境、仅进餐时段），类别只有 8 个，且计算实验用的是人工构造训练集而非真实婴儿影像直接训练；作者也仅&quot;讨论&quot;了对人类与机器学习的启示，未做因果干预。</p><p><strong>跨主题关联</strong>：直指 <code>topics/intelligence-self-learning/index.md</code> 中&quot;知识嫁接与有意义学习&quot;的讨论，并与 <code>topics/ai-brain/index.md</code> 的&quot;存入即关联、关联密度决定可检索性&quot;在结构上高度同构——两者都在说<strong>结构比数量重要</strong>。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-steerbench-work-智能体-按下回车之前-该不该停" tabindex="-1">6. SteerBench-Work：智能体&quot;按下回车之前&quot;该不该停 <a class="header-anchor" href="#_6-steerbench-work-智能体-按下回车之前-该不该停" aria-label="Permalink to &quot;6. SteerBench-Work：智能体&quot;按下回车之前&quot;该不该停&quot;">​</a></h3><p><strong>原文</strong>：长时程智能体通过工具行动，单步就可能发出邮件、合并 PR 或划转付款。真正的控制点不是&quot;想什么&quot;，而是行动边界前那个&quot;执行 / 挂起待审&quot;的决策。作者发布 SteerBench-Work：以真实公开事故为锚、覆盖七类职场场景的双向基准，v2026-05 含 106 个场景。</p><p><strong>深度扩展</strong>：arXiv:2608.12654（2026-08-12）。这个基准抓住了一个被现有评测忽略的决策点：<strong>行动边界（action boundary）</strong>。给智能体打分的方式通常是&quot;任务是否完成&quot;，但对一个能发邮件、合并 PR、划付款的智能体，真正致命的问题出现在&quot;这一步要不要执行&quot;的瞬间——错误分两类，误放行（proceed 了不该 proceed 的）与误拦截（hold 了本该执行的），而绝大多数基准只惩罚前者。</p><p>SteerBench-Work 的四项设计值得逐个看。其一，<strong>事故锚定（incident-anchored）</strong>：106 个场景源自真实公开事故，而非人工臆想，保证&quot;该拦截&quot;的情形确有现实对应。其二，<strong>双向（bidirectional）</strong>：proceed 与 hold 标签近乎各半，使两类错误获得几乎相同的考察机会——这是纠正&quot;过度保守也能拿高分&quot;的关键。其三，<strong>证据反转镜像（evidence-reversed mirrors）</strong>：同一场景配一份证据被反转的版本，正确决策随之翻转。这直接测&quot;模型是在读证据还是在读表面模式&quot;，是最有信息量的设计。其四，<strong>校准控制项</strong>：用于检测模型是否靠固定倾向（一律 hold）刷分。</p><p>七个领域覆盖研发运维、客服、金融、法务、医疗、HR、安全——都是&quot;单步不可逆&quot;的高代价场景。模型输入只有拟执行动作与可用证据，输出门控决定，按双向错误计分。这与&quot;智能体是否该有撤销/预览机制&quot;的工程实践互为表里：先能量化&quot;该不该停&quot;，才能谈&quot;停得对不对&quot;。</p><p>局限：场景只有 106 个，标签由作者判定；&quot;证据反转&quot;需要人工构造，反转本身可能引入不自然之处；基准只测单点决策，不测&quot;多次误放行的累积风险&quot;。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code> 中智能体权限与人工在环设计相接；也是 <code>topics/ai-brain/index.md</code> &quot;外脑写入/推送前是否需人审&quot;问题的量化版本——两者共用同一个&quot;边界前门控&quot;结构。</p><hr><h3 id="_7-摇摆的裁判-llm-评判者的-认知稳定性-压力测试" tabindex="-1">7. 摇摆的裁判：LLM 评判者的&quot;认知稳定性&quot;压力测试 <a class="header-anchor" href="#_7-摇摆的裁判-llm-评判者的-认知稳定性-压力测试" aria-label="Permalink to &quot;7. 摇摆的裁判：LLM 评判者的&quot;认知稳定性&quot;压力测试&quot;">​</a></h3><p><strong>原文</strong>：LLM 裁判已是评测、在线打分与奖励建模的基础设施，但通常只用黄金数据上的准确率验证——准确率说明不了它在重复提问、被质疑、被持续施压时是否还站得住。作者提出 Wiggle Framework，把稳健性拆成三维：机械一致性、单轮信念、多轮持久性，并在 14 类任务上测了 9 个前沿模型。</p><p><strong>深度扩展</strong>：arXiv:2608.12645（2026-08-12）。这篇的问题意识很锋利：<strong>我们用 LLM 当裁判，却用最容易被游戏化的指标（黄金集准确率）来验证裁判</strong>。准确率高只说明在&quot;标准问法&quot;下对，不说明在用户改写、反问、连续施压时仍是同一个判断。</p><p>Wiggle Framework 的三维分解有明确的心理测量学血统，但被移植得很干净。<strong>机械一致性（Mechanical Consistency）</strong>：同一内容重新表述、换框架（reframing）后，判断是否漂移——测的是&quot;表述不变性&quot;，这与人类信度检验中的重测信度同构。<strong>单轮信念（Single-turn Conviction）</strong>：面对一次明确挑战（&quot;你确定吗？我认为是 X&quot;），是否改口——测的是抗一次劝服。<strong>多轮持久性（Multi-turn Persistence）</strong>：在持续或<strong>自适应</strong>施压下（对方根据裁判的回答调整话术）是否守住——这一维最接近真实对抗场景，也是最容易被&quot;讨好型&quot;模型击穿的地方。</p><p>测量面覆盖 9 个前沿模型、14 类评判任务（安全、毒性、AI 写作检测、政治回应评估等）。任务选择有讲究：这几类的共同点是&quot;正确答案有社会争议性、模型存在训练偏好&quot;，恰好是稳定性最容易崩的地方。一个隐含的重要区分是：<strong>稳定 ≠ 正确</strong>。一个固执错误的裁判三维全满，仍然无用；因此该框架的价值在于与准确率<strong>联合</strong>解读——高准确 + 低稳定 = 靠运气踩到黄金集，低准确 + 高稳定 = 系统性偏见。</p><p>工程意义：如果奖励模型（RM）在多轮施压下会滑，那么 RLHF 的训练信号本身就不稳定，模型可以学会&quot;施压即得分&quot;；如果在线打分的裁判会因措辞而漂移，那么 A/B 结果的方差里有一大块是裁判噪声。这套框架把&quot;裁判质量&quot;从一次性指标变成可分解的动态剖面。</p><p>局限：14 类任务的施压话术由作者设计，覆盖面有限；&quot;稳定&quot;的黄金标准仍是作者标注；多轮自适应施压的强度未做参数化扫描（不同压力梯度下的临界点更值得报告）。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code> 中评测与奖励建模管线相接；其&quot;被质疑就改口&quot;的失效模式，正是 <code>topics/ai-brain/index.md</code> 所讨论的外部记忆应有的作用——<strong>记忆的作用之一就是抵抗会话内的说服漂移</strong>。</p>',62)])])}const l=t(s,[["render",u]]);export{p as __pageData,l as default};
